    mes "Ah, You there, Good. So, Let me check mushrooms first?"
    next()
    v.Mushroom1 = count_item(1069)
    v.Mushroom2 = count_item(1070)
    v.thief_item1 = v.Mushroom1 * 3
    v.thief_item2 = v.Mushroom2
    v.Total_Mushroom = v.thief_item1 + v.thief_item2
    v.money_thief = ((v.thief_item1 * 5) + (v.thief_item2 * 2)) + 200
    mes "[Thief Guide]"
    if v.Mushroom1 == 0 then goto MH2 end
    mes(("You brought Orange Net Mushroom " .. v.Mushroom1) .. " ea .")
