    goto TotalMH
    ::TotalMH::
    if v.Total_Mushroom > 25 then goto HightMH end
    if v.Total_Mushroom == 25 then goto MediamMH end
    mes(("Total grades are... err..  ^FF0000" .. v.Total_Mushroom) .. "^000000 degrees.")
    next()
    mes "[Thief Guide]"
    mes "oh C'mon! Go get more!"
    close()
    do return end
    ::HightMH::
    mes(("Total grades are... err..  ^0000FF" .. v.Total_Mushroom) .. "^000000 degrees.")
    next()
    mes "[Thief Guide]"
    mes "Ohho. Above 25, cool. Fine. You pass the Test!"
    goto Final
    ::MediamMH::
    mes(("Total grades are... err..  ^0000FF" .. v.Total_Mushroom) .. "^000000 degrees.")
    next()
    mes "[Thief Guide]"
    mes "Fine. You pass the Test."
    goto Final
    ::Final::
    mes "Fine Fine! We are going to start the Ceremony!"
    next()
    if player.sex == 0 then goto L0102z end
    mes "[Brad]"
    mes(("'Gentleman, " .. char_info(0)) .. ".'")
    next()
    goto L01020z
