    mes "[Brad]"
    mes(("'Lady, " .. char_info(0)) .. ".'")
    next()
    goto L01020z
    ::L01020z::
    mes "'You passed the official Thief Test'"
    v.Mushroom1 = 0
    v.Mushroom2 = 0
    v.thief_item1 = 0
    v.thief_item2 = 0
    v.Total_Mushroom = 0
    take_item(1069, 99)
    take_item(1070, 99)
    unequip_all()
    job_change(6)
    next()
    mes "[Brad]"
    mes "It is a small Subsidy for a Newbie like you. But spend it wherever you want."
    player.zeny = player.zeny + v.money_thief
